catalog_script_client.script:
function onSubmit() {
   //Type appropriate comment here, and begin script below


	//Make sure the reported date is after the incident date
	var reported_date = new Date(g_form.getValue("inc_date_time"));
	var incident_date = new Date(g_form.getValue("inc_report_date_time"));

	if (reported_date > incident_date){
		//g_form.addErrorMessage(getMessage("x_hccc_hoc_ohs.accident_date_cannot_be_before_reported_date"));
		getMessage("x_hccc_hoc_ohs.accident_date_cannot_be_before_reported_date", function(msg) {g_form.addErrorMessage(msg);});
		return false;
	}



}
